import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_packages(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            key = f\"{name} ({fw['framework']})\"
            pkgs = {}
            for p in fw.get('topLevelPackages', []):
                pkgs[p['id']] = p['resolvedVersion']
            result[key] = pkgs
    return result

b = get_packages(baseline)
a = get_packages(after)

changes = []
unchanged = []

all_keys = sorted(set(list(b.keys()) + list(a.keys())))
for key in all_keys:
    bp = b.get(key, {})
    ap = a.get(key, {})
    all_pkgs = sorted(set(list(bp.keys()) + list(ap.keys())))
    for pkg in all_pkgs:
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av:
            changes.append((key, pkg, bv, av))
        else:
            unchanged.append((key, pkg, bv))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]}: {c[1]} {c[2]} -> {c[3]}')
else:
    print('  None - conversion is version-neutral!')

print(f'\n=== UNCHANGED: {len(unchanged)} package entries ===')
"

